<script type="module">
	const SPACE = "gradio/pr-13657-private-space-test";
	const VERSIONS = [
		{
			el: "out-published",
			url: "https://cdn.jsdelivr.net/npm/@gradio/client/dist/index.min.js"
		},
		{
			el: "out-pr",
