<h2>PR #13655 — <code>dist/index.min.js</code>: published package vs PR build</h2>
<p>
	Space under test: <b>gradio/pr-13655-cdn-test</b> (public — no token needed).
</p>
<p>
	<button id="run">Run checks</button>
</p>
<div class="cols">
	<div class="col"><h3>Published @gradio/client (jsDelivr <code>dist/index.min.js</code>)</h3><pre id="out-published">–</pre></div>
	<div class="col"><h3>This PR's real <code>dist/index.min.js</code> (npm-previews CDN)</h3><pre id="out-pr">–</pre></div>
</div>

<script type="module">
	const SPACE = "gradio/pr-13655-cdn-test";
	const VERSIONS = [
		{
			el: "out-published",
			url: "https://cdn.jsdelivr.net/npm/@gradio/client/dist/index.min.js"
		},
		{
			el: "out-pr",
			// per-commit URL — if new commits land on the PR, swap in the latest
			// head sha from the gradio-pr-bot comment's CDN link
			url: "https://huggingface.co/buckets/gradio/npm-previews/resolve/1c347ae7e9b0c844fc453ca51c7fb46be8f542e4/index.min.js"
		}
	];

	async function run_checks(v, print) {

		const check = async (label, fn) => {
			try {
				const out = await fn();
				print(`✅ [${label}] ${out}`, "pass");
			} catch (e) {
				print(`❌ [${label}] rejected (${e?.constructor?.name}): ${e?.message ?? e}`, "fail");
			}
		};

		// 1. Is dist/index.min.js a real shipped file, or jsDelivr's auto-minified
		// fallback? jsDelivr stamps fallbacks with a banner naming the original file.
		await check("does dist/index.min.js really exist in the package?", async () => {
			const head = (await (await fetch(v.url)).text()).slice(0, 220);
			if (head.includes("Minified by jsDelivr")) {
				throw new Error(
					`NO — the package ships no dist/index.min.js; jsDelivr is silently ` +
						`auto-minifying another file as a fallback (issue #10028). Banner:\n---\n${head}\n---`
